// This file is generated by Claude Opus 5.5
//
// It generates a nice wave animation to use as our loading icon.

import { type PropsWithChildren, useEffect, useRef } from "react";
import { Trans } from "react-i18next";
import { classNames } from "../utils/classNames";

// The wave is drawn in a 60 by 20 box, with the line in the middle
const WIDTH = 60;
const MIDDLE = 10;

// A sine wave moving to the left, for x at time t (seconds)
function wave(x: number, t: number, wavelength: number, period: number) {
  return Math.sin(2 * Math.PI * (x / wavelength + t / period));
}

// Slowly moves between 1 - amount and 1, so the height varies over time
function drift(t: number, period: number, amount: number) {
  return 1 - amount / 2 + (amount / 2) * Math.sin((2 * Math.PI * t) / period);
}

// Flat at both ends and tallest around the middle, where the tallest point
// slowly sways from side to side.
function envelope(x: number, t: number) {
  const center = WIDTH / 2 + 6 * Math.sin((2 * Math.PI * t) / 4.3);
  const flatEnds = Math.sin((Math.PI * x) / WIDTH) ** 2;
  return flatEnds * Math.exp(-(((x - center) / 18) ** 2));
}

function toPath(y: (x: number) => number) {
  let path = "";
  for (let x = 0; x <= WIDTH; x++) {
    path += `${x === 0 ? "M" : "L"}${x} ${(MIDDLE + y(x)).toFixed(2)}`;
  }
  return path;
}

// A wave (Ondu comes from "onde"), with a faint wave behind it moving the
// other way. Redrawn every frame without re-rendering.
function Wave() {
  const backRef = useRef<SVGPathElement>(null);
  const frontRef = useRef<SVGPathElement>(null);

  useEffect(() => {
    let frame: number;

    const draw = (now: number) => {
      const t = now / 1000;

      const back = toPath(
        (x) => 3 * drift(t, 2.9, 0.5) * envelope(x, t) * wave(x, -t, 14, 1.2),
      );
      const front = toPath(
        (x) => 4.5 * drift(t, 3.7, 0.3) * envelope(x, t) * wave(x, t, 10, 0.8),
      );

      backRef.current?.setAttribute("d", back);
      frontRef.current?.setAttribute("d", front);
      frame = requestAnimationFrame(draw);
    };

    frame = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(frame);
  }, []);

  return (
    <svg
      width="60"
      height="20"
      viewBox="0 0 60 20"
      className="mx-auto [mask-image:linear-gradient(to_right,transparent,black_25%,black_75%,transparent)]"
    >
      <title>
        <Trans i18nKey="loading.text">Loading</Trans>
      </title>
      <path
        ref={backRef}
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        opacity="0.3"
      />
      <path
        ref={frontRef}
        fill="none"
        stroke="currentColor"
        strokeWidth="2.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function Loading({
  children,
  fullPage = false,
}: PropsWithChildren<{ fullPage?: boolean }>) {
  return (
    <div
      className={classNames([
        // Only fades in when loading takes a while, so quick loads don't flash
        "w-full h-full content-center transition-opacity duration-300 delay-300 starting:opacity-0",
        // Loading the whole page gets the accent colour, loading content
        // inside the page stays quiet.
        fullPage ? "text-accent-500" : "text-page-fg-muted",
      ])}
    >
      <div className="relative">
        <Wave />

        {/* Shown below the wave without moving it when it appears */}
        <div className="absolute inset-x-0 top-full text-page-fg-muted">
          {children}
        </div>
      </div>
    </div>
  );
}
